TYPE
    GateState : INT (0 := 0, 1 := 1, 2 := 2, 3 := 3);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state         : GateState := 0;
    openBtnPrev   : BOOL := FALSE;
    closeBtnPrev  : BOOL := FALSE;
END_VAR

IF state = 0 THEN
    motorUp   := FALSE;
    motorDown := FALSE;
    IF openBtn AND NOT openBtnPrev AND NOT openLimit THEN
        state := 1;
    ELSIF closeBtn AND NOT closeBtnPrev AND NOT closeLimit THEN
        state := 2;
    END_IF
ELSIF state = 1 THEN
    IF obstacle THEN
        motorUp   := FALSE;
        errorFlag := TRUE;
        state := 3;
    ELSIF openLimit THEN
        motorUp := FALSE;
        state := 0;
    ELSE
        motorUp := TRUE;
    END_IF
ELSIF state = 2 THEN
    IF closeLimit THEN
        motorDown := FALSE;
        state := 0;
    ELSIF obstacle THEN
        motorDown := FALSE;
        state := 1;
    ELSE
        motorDown := TRUE;
    END_IF
ELSIF state = 3 THEN
    IF openBtn AND closeBtn AND NOT obstacle THEN
        state := 0;
    END_IF;
END_IF

openBtnPrev  := openBtn;
closeBtnPrev := closeBtn;

errorFlag := (state = 3);

END_FUNCTION_BLOCK
